import datetime
from typing import Optional
import uuid
from sqlalchemy import (
    CheckConstraint,
    DateTime,
    SmallInteger,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column
from app.db.session import Base


class PostPublication(Base):
    __tablename__ = "post_publications"

    # Unique publication identifier generated by PostgreSQL
    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )

    # User ID from Neon Auth token (indexed for user isolation lookups)
    user_id: Mapped[str] = mapped_column(Text, nullable=False, index=True)

    # The post to publish
    post_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), nullable=False
    )

    # Publishing platform (currently only linkedin)
    platform: Mapped[str] = mapped_column(Text, nullable=False)

    # Publication lifecycle status: pending, publishing, published, or failed
    status: Mapped[str] = mapped_column(
        Text, nullable=False, server_default="pending"
    )

    # Number of publish attempts made by the background job
    attempts: Mapped[int] = mapped_column(
        SmallInteger, nullable=False, server_default="0"
    )

    # Earliest time this publication may be retried (for rate limits or temporary failures)
    not_before: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    # Timestamp when a worker claimed this row for processing
    claimed_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    # Normalized error code on failure
    error_code: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Short sanitized error details (no tokens or post content)
    error_detail: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # External platform identifier (e.g. LinkedIn post URN)
    external_id: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Timestamp when successfully published to the platform
    published_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    # Audit timestamps
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )
    updated_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )

    __table_args__ = (
        CheckConstraint(
            "platform IN ('linkedin')",
            name="ck_post_publications_platform",
        ),
        CheckConstraint(
            "status IN ('pending', 'publishing', 'published', 'failed')",
            name="ck_post_publications_status",
        ),
        UniqueConstraint(
            "post_id", "platform", name="uq_post_publications_post_id_platform"
        ),
    )
